using System;using System.Linq;using UnityEngine;using UnityEditor;
public static class Native1112Weights{public static string Run(){var go=Resources.Load<GameObject>("Kemono/Kemono_Character");return string.Join("\n",go.GetComponentsInChildren<SkinnedMeshRenderer>().Select(s=>{var w=s.sharedMesh.boneWeights;var used=w.SelectMany(x=>new[]{(x.boneIndex0,x.weight0),(x.boneIndex1,x.weight1),(x.boneIndex2,x.weight2),(x.boneIndex3,x.weight3)}).Where(x=>x.Item2>.01f).GroupBy(x=>s.bones[x.Item1].name).OrderByDescending(g=>g.Count());return s.name+" weights="+w.Length+" minSum="+w.Min(x=>x.weight0+x.weight1+x.weight2+x.weight3)+" used="+string.Join(",",used.Select(g=>g.Key+":"+g.Count()));}));}}
